?><!doctype html><html lang="<?php echo substr($contentLang,0,2); ?>" dir="<?php echo $meta['dir']; ?>"><head><meta charset="utf-8"><title><?php echo dol_escape_htmltag($sop['ref'].' '.$sop['title']); ?></title><style>body{font:14px/1.7 Tahoma,Arial,"Microsoft YaHei",sans-serif;color:#172033;max-width:900px;margin:30px auto}header{border-bottom:3px solid #0d1b3e;padding-bottom:15px}h1{margin:8px 0}h2{color:#102650}section{break-inside:avoid;margin:22px 0}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.meta div{border:1px solid #ccdce4;padding:8px}.warn{border:2px solid #d4a017;background:#fff8df;padding:12px}.escalate{border-inline-start:5px solid #b42318;background:#fff0ee;padding:12px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()"><?php echo $langs->trans('Print'); ?></button><header><strong><?php echo dol_escape_htmltag($sop['ref']).' · '.$langs->trans('Revision').' '.(int)$sop['revision_no']; ?></strong><h1><?php echo dol_escape_htmltag($sop['title']); ?></h1><p><?php echo $langs->trans('EffectiveDate').': '.dol_escape_htmltag($sop['effective_date']?:'—'); ?></p></header><section><h2><?php echo $langs->trans('WhenApplies'); ?></h2><p><?php echo nl2br(dol_escape_htmltag($sop['applicability']?:$langs->trans('GeneralProcedure'))); ?></p><div class="meta"><?php foreach(array('Country'=>$sop['country_code'],'POL'=>$sop['pol'],'POD'=>$sop['pod'],'ShippingLine'=>$sop['shipping_line'],'ServiceType'=>$sop['service_type'],'ContainerType'=>$sop['container_type'],'Incoterm'=>$sop['incoterm'],'CargoType'=>$sop['cargo_type']) as $label=>$value){ ?><div><small><?php echo $langs->trans($label); ?></small><br><strong><?php echo dol_escape_htmltag($value?:$langs->trans('All')); ?></strong></div><?php } ?></div></section><?php $list=function($label,$value,$ordered=false,$class='')use($langs){$items=OperationsSopService::decodeList($value);if(!$items)return;?><section class="<?php echo $class; ?>"><h2><?php echo $langs->trans($label); ?></h2><<?php echo $ordered?'ol':'ul'; ?>><?php foreach($items as $item){ ?><li><?php echo nl2br(dol_escape_htmltag($item)); ?></li><?php } ?></<?php echo $ordered?'ol':'ul'; ?>></section><?php };$list('RequiredInformation',$sop['required_information']);$list('ProcedureSteps',$sop['procedure_steps'],true);$list('RequiredDocuments',$sop['required_documents']);$list('ImportantWarnings',$sop['warnings'],false,'warn');if($sop['escalation_instructions']){ ?><section class="escalate"><h2><?php echo $langs->trans('EscalationInstructions'); ?></h2><p><?php echo nl2br(dol_escape_htmltag($sop['escalation_instructions'])); ?></p></section><?php } ?></body></html>
